    43→  //             for processing at the appropriate slot).
    44→  const currentSlotWithGossipDisparity = chain.clock.currentSlotWithGossipDisparity;
    45→  if (currentSlotWithGossipDisparity < blockHeader.slot) {
    46→    throw new DataColumnSidecarGossipError(GossipAction.IGNORE, {
    47→      code: DataColumnSidecarErrorCode.FUTURE_SLOT,
    48→      currentSlot: currentSlotWithGossipDisparity,
    49→      blockSlot: blockHeader.slot,
    50→    });
    51→  }
    52→
    53→  // 4) [IGNORE] The sidecar is from a slot greater than the latest finalized slot -- i.e. validate that
    54→  //             sidecar.slot > compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)
    55→  const finalizedCheckpoint = chain.forkChoice.getFinalizedCheckpoint();
    56→  const finalizedSlot = computeStartSlotAtEpoch(finalizedCheckpoint.epoch);
    57→  if (blockHeader.slot <= finalizedSlot) {
